const REGION_NAME = "Umbral Dominion";

// Find all matching Regions on the current canvas
const regions = canvas.regions.placeables
    .map(placeable => placeable.document)
    .filter(region => region.name === REGION_NAME);

if (!regions.length) {
    ui.notifications.warn(`No "${REGION_NAME}" regions found.`);
    return;
}

let added = 0;

for (const region of regions) {
    // Don't add Difficult Terrain twice
    const alreadyExists = region.behaviors.some(
        behavior =>
            behavior.type === "modifyMovementCost" &&
            behavior.name === "Difficult Terrain"
    );

    if (alreadyExists) continue;

    await region.createEmbeddedDocuments("RegionBehavior", [{
        name: "Difficult Terrain",
        type: "modifyMovementCost",
        system: {
            difficulties: {
                walk: 2,
                fly: 1,
                swim: 1,
                burrow: 1,
                deploy: 1,
                travel: 1
            }
        },
        disabled: false
    }]);

    added++;
}

if (added > 0) {
    ui.notifications.info(
        `Difficult Terrain applied to ${added} Umbral Dominion region${added === 1 ? "" : "s"}.`
    );
} else {
    ui.notifications.info(
        `All Umbral Dominion regions already have Difficult Terrain.`
    );
}
